use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " A single source in the [`SourceMap`]."] pub struct SourceFile { # [doc = " The name of the file that the source came from. Source that doesn't"] # [doc = " originate from files has names between angle brackets by convention"] # [doc = " (e.g., `<anon>`)."] pub name : FileName , # [doc = " The complete source code."] pub src : Option < Arc < String > > , # [doc = " The source code's hash."] pub src_hash : SourceFileHash , # [doc = " Used to enable cargo to use checksums to check if a crate is fresh rather"] # [doc = " than mtimes. This might be the same as `src_hash`, and if the requested algorithm"] # [doc = " is identical we won't compute it twice."] pub checksum_hash : Option < SourceFileHash > , # [doc = " The external source code (used for external crates, which will have a `None`"] # [doc = " value as `self.src`."] pub external_src : FreezeLock < ExternalSource > , # [doc = " The start position of this source in the `SourceMap`."] pub start_pos : BytePos , # [doc = " The byte length of this source."] pub source_len : RelativeBytePos , # [doc = " Locations of lines beginnings in the source code."] pub lines : FreezeLock < SourceFileLines > , # [doc = " Locations of multi-byte characters in the source code."] pub multibyte_chars : Vec < MultiByteChar > , # [doc = " Locations of characters removed during normalization."] pub normalized_pos : Vec < NormalizedPos > , # [doc = " A hash of the filename & crate-id, used for uniquely identifying source"] # [doc = " files within the crate graph and for speeding up hashing in incremental"] # [doc = " compilation."] pub stable_id : StableSourceFileId , # [doc = " Indicates which crate this `SourceFile` was imported from."] pub cnum : CrateNum , }